"""Shared light premium QueueMind theme."""
import streamlit as st

def apply_theme():
    st.markdown("""<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
:root{--bg:#FAF9F6;--surface:#FFF;--soft:#F6F8FB;--navy:#1E3A5F;--ink:#0F172A;--body:#334155;--muted:#6B7280;--coral:#F97360;--border:#E8E4DE;--green:#2E9F6B;--amber:#D89B2B;--red:#DC4C4C}
html,body,[data-testid="stAppViewContainer"]{background:var(--bg);color:var(--body);font-family:Inter,"Segoe UI",sans-serif}[data-testid="stHeader"],footer{display:none}[data-testid="stSidebar"]{background:#FFF;border-right:1px solid var(--border)}[data-testid="stSidebar"] *{color:var(--navy)}.block-container{padding:1.7rem 2.2rem;max-width:1500px}.eyebrow,.metric-label{font-size:12px;letter-spacing:.08em;color:var(--muted);font-weight:700}.page-title{font-size:38px;color:var(--ink);font-weight:700;margin:4px 0}.subtle,.metric-detail{color:var(--muted);font-size:14px}.card{background:#FFF;border:1px solid var(--border);border-radius:14px;padding:17px;margin-bottom:12px;box-shadow:0 4px 18px rgba(30,58,95,.045)}.metric-value{font-size:31px;color:var(--ink);font-weight:700;margin:6px 0}.status{font-size:12px;font-weight:700;letter-spacing:.07em}.status.normal{color:var(--green)}.status.warning{color:var(--amber)}.status.critical{color:var(--red)}button[kind="secondary"]{border-color:var(--border)!important;background:#FFF!important;color:var(--navy)!important;border-radius:9px!important}button[kind="primary"]{background:linear-gradient(90deg,#F97360,#FF7E6D)!important;border:0!important;border-radius:9px!important}.impact-row{background:#FFF;border:1px solid var(--border);border-radius:12px;padding:12px 14px;margin:8px 0}.impact-row.current{border-color:#F2B6AA;background:#FFF9F7}.impact-row.recommended{border-color:#B8E3CC;background:#F6FCF8}.bar{height:7px;border-radius:8px;background:#ECEFF3;overflow:hidden;margin-top:5px}.fill{height:100%;border-radius:8px}.pill{font-size:11px;font-weight:700;padding:4px 8px;border-radius:12px;display:inline-block}.pill.normal{color:#2E9F6B;background:#EAF7F0}.pill.warning{color:#D89B2B;background:#FFF6E5}.pill.critical{color:#DC4C4C;background:#FDECEC}div[data-baseweb="select"]>div{background:#FFF!important;border-color:var(--border)!important}</style>""",unsafe_allow_html=True)
